        cards.append((a, b, i))

    total = [0, 0]
    for card in cards:
        if card[0] > 0:
            total[0] += 1
        else:
            total[0] -= 1
        if card[1] > 0:
            total[1] += 1
        else:
            total[1] -= 1

    if total[0] != 0 or total[1] != 0:
        return "NO\n"

    same_front_back = []
    diff_front_back = []

    for card in cards:
        if card[0] > 0 and card[1] > 0:
            same_front_back.append(card)
        elif card[0] < 0 and card[1] < 0:
            same_front_back.append(card)
        else:
            diff_front_back.append(card)

    if not same_front_back and len(diff_front_back) % 2 != 0:
        return "NO\n"

    def valid_balanced(sequence):
        balance = 0
        for x in sequence:
            balance += x if x >= 0 else abs(x)
            if balance < 0:
                return False
        return balance == 0

    result = []
    for i in range(n):
        a, b, idx = same_front_back[i % len(same_front_back)]
