def solve_k_covering(edges, n1, n2, m, k):
    degree_u = [0] * (n1 + 1)
    degree_v = [0] * (n2 + 1)
    for u, v, i in edges:
        degree_u[u] += 1
        degree_v[v] += 1

    covering_edges = []
    for u, v, i in edges:
        covering_edges.append(i)

    return len(covering_edges), covering_edges

