    pref = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                pref[i].append((costs[i][j], j))
        pref[i].sort()
        pref[i] = [j for (_, j) in pref[i]]

    # Current partner assignment: partner[i] = j means city i is partner of city j
    partner = [0] * n

    # Initialize with a simple pairing
    for i in range(0, n - 1, 2):
        partner[i] = i + 1
        partner[i + 1] = i

    # If n is odd, the last city gets partner 0 (this will be adjusted)
    if n % 2 == 1:
        partner[n - 1] = 0
        partner[0] = n - 1

    # Keep trying to find blocking pairs
    for _ in range(n * n * n + 1):
        made_change = False
        for i in range(n):
            for j in pref[i]:
                # Skip if already other city or already partner
                if j == i or j == partner[i]:
                    continue

                # Check if j prefers i over current partner
                j_prefers_i = False
                if partner[j] == i:
                    continue
                if j != 0 or partner[i] != 0 or costs[i][j] < costs[i][partner[i]]:
                    j_prefers_i = costs[j][i] < costs[j][partner[j]]

                # Check if i prefers j over current partner
                i_prefers_j = costs[i][j] < costs[i][partner[i]]

                if i_prefers_j and j_prefers_i:
                    # Blocking pair found! Make them partners
                    partner[i] = j
                    partner[j] = i
                    made_change = True
                    break
            if made_change:
                break

        # If no changes made, we've found a stable matching
        if not made_change:
            break

    # Check if we have valid matching (everyone has a partner)
    valid = True
    for i in range(n):
        if partner[i] == -1 or partner[partner[i]] != i:
            valid = False
            break

    if not valid:
        return "-1\n"

    # Output results (1-indexed)
    result = [str(partner[i] + 1) for i in range(n)]
    return '\n'.join(result) + '\n'

