def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges.append({'u': x, 'v': y, 'w': w, 'id': i})
        adj[x].append((y, i))
        adj[y].append((x, i))

    def is_connected(remove_edge_id):
        if remove_edge_id == -1:
            # Check all paths normally
            visited = [False] * (n + 1)
            visited[s] = True
            q = deque([s])
            while q:
                u = q.popleft()
                if u == t:
                    return True
                for v, idx in adj[u]:
                    if not visited[v]:
                        # Skip removed edge
                        if idx != remove_edge_id:
                            visited[v] = True
                            q.append(v)
            return visited[t]
        else:
            # Standard BFS without explicit edge removal (alternative check)
            visited = [False] * (n + 1)
            visited[s] = True
            q = deque([s])
            while q:
                u = q.popleft()
                if u == t:
                    return True
                for v, idx in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        q.append(v)
            return visited[t]

    def remove_edge(idx):
        visited = [False] * (n + 1)
        visited[s] = True
        q = deque([s])
        while q:
            u = q.popleft()
            if u == t:
                return True
            for v, e_idx in adj[u]:
                if e_idx != idx and not visited[v]:
                    visited[v] = True
                    q.append(v)
        return visited[t]

    # Check if already disconnected with 0 edges
    if not is_connected(-1):
        return "0\n0"

    # Check with 1 edge removal
    min_cost = float('inf')
    best_pair1 = None
    for i, e in enumerate(edges):
        if remove_edge(e['id']):  # e['id'] is index in original 0-indexed edges
            result = not is_connected(i)
            if result:
                if e['w'] < min_cost:
                    min_cost = e['w']
                    best_pair1 = [i]

    if best_pair1:
        return f"{min_cost}\n{len(best_pair1)}\n{' '.join(map(str, best_pair1))}"

    # Check with 2 edge removals
    best_pair2_idx = None
    best_cost2 = float('inf')

    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            # Check if path disconnects AND s-t not connected initially
            if not remove_edge(i) or not remove_edge(j):
                continue
            idx1 = i
            idx2 = j
            if remove_edge(idx1):
                continue
            if remove_edge(idx2):
                continue

            # Both edges need to be on some paths, remove both
            # Verify they're edge indices
            edge_indices = [e['id'] for e in edges]

            cost = edges[i]['w'] + edges[j]['w']

            if cost < best_cost2:
                best_cost2 = cost
                best_pair2_idx = (edge_indices[i], edge_indices[j])

    if best_pair2_idx:
        return f"{best_cost2}\n2\n{best_pair2_idx[0]} {best_pair2_idx[1]}"

    return "-1"

