from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = int(lines[0].split()[0]), int(lines[0].split()[1])
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    initial = tuple(a)
    queue = deque([initial])
    visited = {initial: []}  # state -> path of (x, y) operations

    while queue:
        state = queue.popleft()

        if len(state) == 1 and state[0] == 1:
            ops = [f"{x} {y}" for x, y in visited[state]]
            return "YES\n" + "\n".join(ops)

        if len(state) <= 0 or any(x <= 0 for x in state):
            continue

        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                x, y = state[i], state[j]
                new_val = f(x + y)

                # Build new state by combining elements at i and j
                new_list = list(state)
                new_list.pop(j)
                new_list.pop(i)
                new_list.append(new_val)
                new_state = tuple(sorted(new_list))

                if new_state not in visited:
                    visited[new_state] = visited[state] + [(x, y)]
                    queue.append(new_state)

    return "NO\n"

import math

def is_prime(num):
    """Check if a number is prime"""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.isqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True

def get_order(b, p, n):
    """Get the multiplicative order of b modulo p, must be exactly n"""
    if b % p == 0:
        return None

    # Find the smallest k such that b^k ≡ 1 (mod p)
    current = 1
    for k in range(1, n + 1):
        current = (current * b) % p
        if current == 1:
            if k == n:
                return k
            else:
                return None
    return None

def solution(input_str):
    n, x = map(int, input_str.strip().split())

    # p = n + 1 must be prime for rotatable numbers to exist
    p = n + 1

    if not is_prime(p):
        return "-1\n"

    # Find the largest b < x where 1 < b and b has order n modulo p
    # The order of b mod p must be exactly n

    for b in range(min(x - 1, p - 1), 1, -1):
        if b <= 0:
            continue

        # Check if b has order exactly n mod p
        # Order is the smallest k such that b^k ≡ 1 (mod p)
        # For order n, we need b^n ≡ 1 (mod p) and no smaller k works

        if pow(b, n, p) != 1:
            continue

        # Now check no smaller k gives 1
        if get_order(b, p, n) == n:
            return f"{b}\n"

    return "-1\n"

