import itertools

def solution(input_str):
    n, r = map(int, input_str.split())

    # Generate all valid integer points within radius r
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    def sum_sq_dist(points_config):
        """Calculate sum of squared Euclidean distances between all pairs"""
        total = 0
        m = len(points_config)
        for i in range(m):
            for j in range(i + 1, m):
                dx = points_config[i][0] - points_config[j][0]
                dy = points_config[i][1] - points_config[j][1]
                total += dx*dx + dy*dy
        return total * 2  # double because we want all pairs (i,j) not just (i<j)

    # Brute force search - enumerate all unique combos of n points up to permutations
    # For n=8, this could be large but the radius constraint limits valid points significantly

    # Precompute squared norms to use shortcut formula
    # sum_{i<j} |P_i - P_j|^2 = n * sum |P_i|^2 - |sum P_i|^2 * 2
    # Actually for all i,j (i != j): = 2n * sum |P_i|^2 - 2 * |sum P_i|^2

    def sum_sq_dist_formula(config):
        n_config = len(config)
        sum_sq_norm = sum(p[0]*p[0] + p[1]*p[1] for p in config)
        sum_vec = (sum(p[0] for p in config), sum(p[1] for p in config))
        sum_sq_vec = sum_vec[0]*sum_vec[0] + sum_vec[1]*sum_vec[1]
        return 2 * n_config * sum_sq_norm - 2 * sum_sq_vec

    # Sort points by distance from origin (descending)
    points_by_sq_dist = sorted(points, key=lambda p: p[0]*p[0] + p[1]*p[1], reverse=True)

    max_score = -1
    best_config = None

    # Try different strategies to avoid full brute force for large n
    # Strategy 1: Fixed-point selection (same point repeated)
    for pt in points_by_sq_dist:
        config = [pt] * n
        score = sum_sq_dist_formula(config)
        if score > max_score:
            max_score = score
            best_config = config

    # Strategy 2: Pair the points to cancel vectors
    if n >= 2:
        for i in range(len(points_by_sq_dist)):
            for j in range(i + 1, len(points_by_sq_dist)):
                config = [points_by_sq_dist[i], points_by_sq_dist[j]] + [points_by_sq_dist[0]] * (n - 2)
                score = sum_sq_dist_formula(config)
                if score > max_score:
                    max_score = score
                    best_config = config

    if n == 2 and len(points_by_sq_dist) >= 2:
        # Special handling for n=2 to get opposite points
        for i in range(len(points_by_sq_dist)):
            candidates_for_second = [p for j, p in enumerate(points_by_sq_dist) if j != i]
            for pt2 in candidates_for_second:
                config = [points_by_sq_dist[i], pt2]
                score = sum_sq_dist_formula(config)
                if score > max_score:
                    max_score = score
                    best_config = config

    # Strategy 3: Try many permutations with fixed high-value points
    if max_score > -1 and best_config is not None:
        # Try cycling through combinations of top points
        for base_points in itertools.combinations(points_by_sq_dist[:min(n, len(points_by_sq_dist)*2)], n):
            config = list(base_points)
            score = sum_sq_dist_formula(config)
            if score > max_score:
                max_score = score
                best_config = config

    # Format output
    output = [str(max_score)]
    for x, y in best_config:
        output.append(f"{x} {y}")

    return "\n".join(output) + "\n"

