    from collections import deque
    queue = deque()
    for c, child in trie[0]['next'].items():
        trie[child]['fail'] = 0
        queue.append(child)

    while queue:
        u = queue.popleft()
        for c, v in trie[u]['next'].items():
            fail_node = trie[u]['fail']
            while fail_node != 0 and c not in trie[fail_node]['next']:
                fail_node = trie[fail_node]['fail']
            if c in trie[fail_node]['next']:
                trie[v]['fail'] = trie[fail_node]['next'][c]
            else:
                trie[v]['fail'] = 0
            queue.append(v)

    # Calculate which positions can be last in a valid match
    out = [set() for _ in range(len(trie))]

    def compute_terminal():
        queue = deque()
        for c, child in trie[0]['next'].items():
            queue.append(child)

        while queue:
            u = queue.popleft()
            for c, v in trie[u]['next'].items():
