    # We track patterns being matched for each node in the trie

    # For each position, we need to track the state in the trie
    # state = current trie node + pattern completions at this node

    dp = {0: 1}  # position 0, at root, 1 way

    for pos in range(1, n + 1):
        new_dp = defaultdict(int)

        for trie_node, count in dp.items():
            for char in ['A', 'C', 'G', 'T']:
                new_node = trie_node
