def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    try:
        t = int(lines[0].strip())
    except:
        return ""

    results = []
    idx = 1

    for _ in range(t):
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        if idx >= len(lines):
            break

        try:
            n = int(lines[idx].strip())
            idx += 1
        except:
            break

        divs = all_divisors(n)

        if len(divs) == 1:
            results.append(str(divs[0]))
            results.append("0")
            continue

        best_order = None
        best_count = len(divs)  # Max possible (all adjacent pairs coprime)

        total = len(divs)
        used = [False] * total
        divs_arr = divs

        def backtrack(path, cost, used_count):
            nonlocal best_count, best_order

            # Prune if current cost already >= best
            if cost >= best_count:
                return

            if len(path) == total:
                # Complete permutation, count coprime pairs including wraparound
                temp_count = 0
                for i in range(total):
                    if gcd(path[i], path[(i+1) % total]) == 1:
                        temp_count += 1
                if temp_count < best_count:
                    best_count = temp_count
                    best_order = list(path)
                return

            for i in range(total):
                if not used[i]:
                    d = divs_arr[i]
                    if path:
                        if gcd(path[-1], d) == 1:
                            continue
                    used[i] = True
                    path.append(d)
                    backtrack(path, cost + 1, used_count + 1)
                    path.pop()
                    used[i] = False

        for i in range(total):
            used[i] = True
            path = [divs_arr[i]]
            backtrack(path, 0, 1)
            path.pop()
            used[i] = False

        results.append(" ".join(map(str, best_order)))
        results.append(str(best_count))

    return "\n".join(results) + "\n"

