def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    line_idx = 1
    result_parts = []

    for _ in range(t):
        n, m = map(int, lines[line_idx].split())
        line_idx += 1

        matrix = []
        for _ in range(n):
            matrix.append(list(map(int, lines[line_idx].split())))
            line_idx += 1

        operations = lines[line_idx]
        line_idx += 1

        for op in operations:
            if op == 'R':
                # Right shift columns: column j gets value from column j-1
                for i in range(n):
                    matrix[i] = [matrix[i][-1]] + matrix[i][:-1]
            elif op == 'L':
                # Left shift columns: column j gets value from column j+1
                for i in range(n):
                    matrix[i] = matrix[i][1:] + [matrix[i][0]]
            elif op == 'D':
                # Down shift rows: row i gets values from row i+1
                # But row i contains column-transposed rows of original... let me reconsider
                # Actually D shifts rows down, so new row 0 = old row n-1, new row i = old row i-1
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    src_row = (i - 1 + n) % n
                    for j in range(n):
                        new_matrix[i][j] = matrix[src_row][j]
                matrix = new_matrix
            elif op == 'U':
                # Up shift rows: row i gets values from row i+1
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    src_row = (i + 1) % n
                    for j in range(n):
                        new_matrix[i][j] = matrix[src_row][j]
                matrix = new_matrix
            elif op == 'I':
                # Invert each row permutation
                for i in range(n):
                    row = matrix[i]
                    # row is [p_1, p_2, ..., p_n], inverse q has q_v = position where value v appears
                    inv_row = [0] * n
                    for pos, val in enumerate(row):
                        inv_row[val - 1] = pos + 1
                    matrix[i] = inv_row
            elif op == 'C':
                # Invert each column permutation
                for j in range(n):
                    # Extract column
                    col = [matrix[i][j] for i in range(n)]
                    # Build inverse: inv_col[v-1] = position where value v appears
                    inv_col = [0] * n
                    for pos, val in enumerate(col):
                        inv_col[val - 1] = pos + 1
                    # Write back column
                    for i in range(n):
                        matrix[i][j] = inv_col[i]

        result_parts.append('\n'.join(' '.join(str(x) for x in row) for row in matrix))

    return '\n\n'.join(result_parts)

from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    # Parse all edges
    for i in range(m):
        line_idx = i + 1
        if line_idx < len(lines):
            parts = lines[line_idx].split()
            ai, bi, ci = map(int, parts)
            edges.append((ai, bi))
            adj[ai].append(bi)
            adj[bi].append(ai)

    # BFS from sink (node n) to compute distances to sink
    # dist_sink[u] represents the shortest distance from u to the sink
    dist_sink = [-1] * (n + 1)
    dist_sink[n] = 0
    queue = deque([n])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist_sink[v] == -1:
                dist_sink[v] = dist_sink[u] + 1
                queue.append(v)

    # Determine directions for each edge
    # Flow moves from nodes further from sink to nodes closer to sink
    result = []
    for ai, bi in edges:
        if dist_sink[ai] < dist_sink[bi]:
            # ai is closer to sink, so flow goes bi → ai
            result.append('1')
        elif dist_sink[bi] < dist_sink[ai]:
            # bi is closer to sink, so flow goes ai → bi
            result.append('0')
        else:
            # Tie-break by node ID to avoid cycles and ensure strict ordering
            if ai < bi:
                result.append('0')
            else:
                result.append('1')

    return '\n'.join(result)

