MOD = 10**9 + 7

def pow_mod(a, b, m):
    result = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        a = (a * a) % m
        b //= 2
    return result

def compute_range_value(l, r):
