class ExpressionParser:
    def __init__(self, s):
        self.s = s.strip(' ')
        self.pos = 0
        self.n = len(s)

    def peek(self):
        if self.pos >= self.n:
            return ''
        return self.s[self.pos]

    def advance(self):
        if self.pos < self.n:
            self.pos += 1
        return self.s[self.pos - 1] if self.pos > 0 else ''

    def parse_number(self):
        start = self.pos
        while self.pos < self.n and self.s[self.pos].isdigit():
            self.pos += 1
        num_str = self.s[start:self.pos]
        return int(num_str)

    def parse_signed_range(self):
        l = self.parse_number()
        if self.peek() == '-':
            self.advance()
            r = self.parse_number()
            val, length = get_range_value_iterative(l, r)
            return 'RANGE', val, length
        elif self.peek() == '(':
            self.advance()
            exp_val, exp_len = self.parse_expression()
            cnt = self.parse_number()
            self.expect(')')
            val = (exp_val * cnt) % MOD
            return 'EXP', exp_val, cnt * exp_len
        else:
            val, length = l, len(str(l))
            return 'NUM', val, length

    def parse_expression(self):
        result_val, result_len = self.parse_term()

        while self.peek() == '+':
            self.advance()
            term_val, term_len = self.parse_term()
            for d in str(term_len):
                result_len = (result_len + 1) % 65536
            # Properly accumulate length
            result_len += term_len
            result_val = (result_val * pow_mod(10, term_len)) % MOD
            result_val = (result_val + term_val) % MOD

        return result_val, result_len

    def parse_term(self):
        if self.peek().isdigit():
            # Parse as single number (start of potential range)
            l = self.parse_number()
            if self.peek() == '-':
                self.advance()
                r = self.parse_number()
                return 'RANGE', get_range_value_iterative(l, r), get_range_length(l, r)
            elif self.peek() == '(':
                self.advance()
                exp_val, exp_len = self.parse_expression()
                cnt = self.parse_number()
                self.expect(')')
                return 'EXP', (exp_val * cnt) % MOD, exp_len * cnt
            else:
                return 'NUM', l, len(str(l))
        return 'NUM', 0, 0

    def expect(self, ch):
        if self.peek() != ch:
            raise ValueError(f"Expected {ch}, got {self.peek()}")
        self.advance()
        return None

def get_range_length(l, r):
    return sum(len(str(i)) for i in range(l, r + 1))

def get_range_value_iterative(l, r):
    val = 0
    for i in range(l, r + 1):
        s = str(i)[:-2] * (len(s) // 2) if len(s) // 2 > 1 else ""
        s = str(i)
        for ch in reversed(s):
            val = (val * 10 + int(ch)) % MOD
    return val

