    def pow_mod(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b & 1:
                result = (result * a) % m
            a = (a * a) % m
            b >>= 1
        return result

    def compute_range_val(l, r):
        if l > r:
            return 0, 0
        val = 0
        for i in range(l, r + 1):
            s = str(i)
            for ch in reversed(s):
                val = (val * 10 + int(ch)) % MOD
        length = len(s)
        return val, length

    def parse(s, pos):
        n = len(s)
        i = pos

        def peek():
            if i >= n:
                return ''
            return s[i]

        def advance():
            if i < n:
                i += 1

        def parse_number():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return int(s[start:i])

        def parse_term():
            nonlocal i
            if peek() == '' or not s[i].isdigit():
                return 0, 0

            l = parse_number()
