                advance()
                r = parse_number()
                return 'RANGE', compute_range_val(l, r)[0], compute_range_val(l, r)[1]
            elif peek() == '(':
                advance()
                exp_val, exp_len = parse()
                advance()  # skip ')'
                cnt = parse_number()
                return 'EXP', (exp_val * cnt) % MOD, exp_len * cnt
            else:
                return 'NUM', l, len(str(l))

        def parse_expr():
            nonlocal i
            val, length = parse_term()

            while peek() == '+':
                advance()
                term_val, term_len = parse_term()
                shift = pow_mod(10, length, MOD)
                val = (val * shift + term_val) % MOD
                length += term_len

            return val, length

        val, length = parse_expr()
        return str(val % MOD), length

    result, _ = parse(s, 0)
    return result

