    type_end_map = {
        '1': [True, True, False, False],   # top and left
        '2': [True, False, False, True],   # top and right
        '3': [False, True, True, False],   # left and bottom
        '4': [False, False, True, True]    # bottom and right
    }

    # Direction vector [top, left, bottom, right]
    direction = [(-1, 0), (0, -1), (1, 0), (0, 1)]

    def count_valid_for_cell(r, c):
        """Count the number of valid pipe types for empty cell at (r,c)"""
        if grid[r][c] != '.':
            return 1

        valid_count = 0
        for ctype in ['1', '2', '3', '4']:
            ends = type_end_map[ctype]
            is_valid = True

            for i in range(4):
                if ends[i]:
                    dr, dc = direction[i]
                    nr, nc = r + dr, c + dc

                    # Check if this direction is at the border
                    if nr < 0 or nr >= n or nc < 0 or nc >= m:
                        # End is at border - valid
                        continue

                    neighbor = grid[nr][nc]
                    if neighbor == '.':
                        # No pipe to connect to, but we have an end -> leaks
                        is_valid = False
                        break

                    # Check if neighbor can connect back
                    # Opposite direction index: (i + 2) % 4
                    if not type_end_map[neighbor][(i + 2) % 4]:
                        is_valid = False
                        break

            if is_valid:
                valid_count += 1

        return valid_count

    def is_pre_filled_leaking(r, c):
        """Check if an existing pipe at (r,c) has any leak"""
        ctype = grid[r][c]
        if ctype == '.':
            return False

        ends = type_end_map[ctype]

        for i in range(4):
            if ends[i]:
                dr, dc = direction[i]
                nr, nc = r + dr, c + dc

                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    # At border - valid connection
                    continue

                neighbor = grid[nr][nc]
                if neighbor != '.':
                    # Check if neighbor has opposite end
                    if not type_end_map[neighbor][(i + 2) % 4]:
                        return True

        return False

    ans = 1
    for r in range(n):
        for c in range(m):
            cell = grid[r][c]
            if cell == '.':
                valid = count_valid_for_cell(r, c)
                if valid == 0:
                    return "0\n"
                ans = (ans * valid) % MOD
            else:
                if is_pre_filled_leaking(r, c):
                    return "0\n"

    return str(ans) + '\n'

