def solution(input_str):
    from collections import defaultdict, deque

    data = input_str.strip().split()
    idx = 0

    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1
    MOD = 1_000_000_007

    clauses = []
    for _ in range(n):
        k = int(data[idx]); idx += 1
        lits = []
        for _ in range(k):
            val = int(data[idx]); idx += 1
            var = val if val > 0 else -val
            neg = (val < 0)
            lits.append((var, neg))
        clauses.append(lits)

    var_to_clauses = defaultdict(list)
    for i, lits in enumerate(clauses):
        for var, neg in lits:
            var_to_clauses[var].append((i, neg))

    appearing = set(var_to_clauses.keys())
    free = m - len(appearing)
    ans = pow(2, free, MOD)

    graph = defaultdict(list)
    for i, lits in enumerate(clauses):
        for j in range(len(lits)):
            for k in range(j + 1, len(lits)):
                v1, n1 = lits[j]
                v2, n2 = lits[k]
                if v1 != v2:
                    graph[v1].append(v2)
                    graph[v2].append(v1)

    visited = set()
    for var in appearing:
        if var not in visited and var in graph:
            comp = []
            stack = [var]
            while stack:
                v = stack.pop()
                if v in visited: continue
                visited.add(v)
                comp.append(v)
                for nb in graph[v]:
                    if nb not in visited:
                        stack.append(nb)

            # For each component with k variables: contributes 2^(k-1) if path, or similar
            if len(comp) == 1:
                ans *= 2
            else:
                ans *= pow(2, len(comp) - 1, MOD)

    return str(ans % MOD)

