def solution(input_string):
    """
    Solves the lantern illumination problem.
    For each test case, determines if we can direct lanterns left or right so that
    every lantern is illuminated by at least one other lantern.
    """
    lines = input_string.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    line_idx = 1
    results = []

    for _ in range(t):
        n = int(lines[line_idx])
        line_idx += 1
        p = list(map(int, lines[line_idx].split()))
        line_idx += 1

        # Try a greedy approach: pass from left to right
        directions = [''] * n
        covered = [False] * n
        valid = True
        attempt = 0

        # Try multiple directional preferences to find a valid configuration
        for direction_preference in [1, 0]:  # 1 = prefer left, 0 = prefer right
            if attempt > 0:
                break

            # Reset for this attempt
            directions = [''] * n
            covered = [False] * n
            attempt += 1

            for i in range(n):
                if covered[i]:
                    continue

                # Skip if this lantern can't be illuminated at all
                can_i_be_illuminated = False

                # Check if this lantern can be illuminated from left (j < i points right)
                for j in range(i):
                    if p[j] > 0 and (i - j) <= p[j]:
                        can_i_be_illuminated = True
                        break

                # Check if this lantern can be illuminated from right (j > i points left)
                for j in range(i + 1, n):
                    if p[j] > 0 and (j - i) <= p[j]:
                        can_i_be_illuminated = True
                        break

                if not can_i_be_illuminated:
                    valid = False
                    break

                # Determine which side is better based on greedy preference
                if preference_left(direction_preference, i, p):
                    # Try to illuminate from left first
                    for j in range(i):
                        if p[j] > 0 and (i - j) <= p[j] and not covered[j]:
                            directions[j] = 'R'
                            directions[i] = 'L'
                            covered[i] = covered[j] = True
                            break
                    else:
