def can_achieve_score(a, b, wA, wB):
    """
    Use DP to check if points (a, b) can be achieved with wA wins for A and wB for B.
    """
    total_sets = wA + wB

    # dp[pointsA][pointsB] = True if state reachable
    # Use dictionary for sparse representation
    dp = {(0, 0): True}

    for set_idx in range(total_sets):
        new_dp = {}
        is_fifth = (set_idx == total_sets - 1)

        for (pa, pb) in dp:
            # Try all possible set scores
            for sa in range(27):  # Points team A scores
                for sb in range(27):  # Points team B scores
                    total_pa = pa + sa
                    total_pb = pb + sb

                    if total_pa > a or total_pb > b:
                        continue

                    # Check if this is a valid set ending
                    a_wins = sa >= 25 and (sa - sb) >= 2
                    b_wins = sb >= 25 and (sb - sa) >= 2

                    # Adjust for 5th set
                    if is_fifth:
                        a_wins = sa >= 15 and (sa - sb) >= 2
                        b_wins = sb >= 15 and (sb - sa) >= 2

                    if a_wins and remaining_wins_for_A(a, b, wA, wB, set_idx + 1) == 0:
                        new_dp[(total_pa, total_pb)] = True
                    elif b_wins and remaining_wins_for_B(a, b, wA, wB, set_idx + 1) == 0:
                        new_dp[(total_pa, total_pb)] = True

        if not new_dp:
            return False

        dp = new_dp

    return (a, b) in dp


def remaining_wins_for_A(target, targetB, wA, wB, sets_played):
