    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    # Tarjan's algorithm for SCC
    discovery_time = [-1] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    timer = 0
    scc_id = [0] * (n + 1)
    scc_count = 0
    scc_nodes = [[] for _ in range(n + 1)]

    def dfs(u):
        nonlocal timer, scc_count
        visited[u] = True
        stack.append(u)
        on_stack[u] = True
        discovery_time[u] = low[u] = timer
        timer += 1

        for v, w in adj[u]:
            if not visited[v]:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], discovery_time[v])

        if low[u] == discovery_time[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_count
                scc_nodes[scc_count].append(node)
                if node == u:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # For each SCC, compute the GCD of all cycles
    scc_gcd = {}

    for scc_idx in range(scc_count):
        nodes = scc_nodes[scc_idx]
        if len(nodes) == 1:
            scc_gcd[scc_idx] = 0
            continue

        root = nodes[0]
        dist = {root: 0}
        queue = [root]
        index = 0
        scc_gcd[scc_idx] = 0
        while index < len(queue):
            u = queue[index]
            index += 1
            for v, w in adj[u]:
                if scc_id[v] != scc_idx:
                    continue
                if v in dist:
                    cycle = dist[v] - dist[u] - w
                    scc_gcd[scc_idx] = gcd(scc_gcd[scc_idx], abs(cycle))
                else:
                    dist[v] = dist[u] + w
                    queue.append(v)

    ans = []
    for v, s, t in queries:
        if s == 0:
            ans.append("YES")
        else:
            g = scc_gcd[scc_id[v]]
            if g == 0 or s % g == 0:
                ans.append("YES")
            else:
                ans.append("NO")

    return "\n".join(ans)

