import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return ''

    try:
        n, k = map(int, lines[0].split())
    except ValueError:
        return ''

    if k == 0:
        # No edges
        keep = list(range(1, n + 1))
        out = ['0', ' '.join(str(i) for i in keep), '']
        return '\n'.join(out)

    edges = []
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            a, b = int(parts[0]), int(parts[1])
            edges.append((min(a, b), max(a, b)))

    # Calculate degree of each member
    degree = [0] * (n + 1)
    for a, b in edges:
        degree[a] += 1
        degree[b] += 1

    # Find members with maximum degree
    max_deg = max(degree[1:])
    candidates = [i + 1 for i, d in enumerate(degree[1:]) if d == max_deg]

    # If all members have the same degree and n > 2, no one keeps token
    unique_degrees = set(degree[1:])
    if len(unique_degrees) == 1 and n > 2:
        keep = []
    else:
        keep = candidates if candidates else [1]

    out_lines = [str(len(keep))]
    out_lines.append(' '.join(str(i) for i in keep) if keep else '')
    out_lines.append('')  # Blank line separator

    # Sort edges and assign weights (0, 1, 2, ...)
    sorted_edges = sorted(edges)
    for i, (a, b) in enumerate(sorted_edges):
        w = i % 2
        out_lines.append(f"{a} {b} {w}")

    return '\n'.join(out_lines)

from collections import defaultdict
from bisect import bisect_right

def solution(input_str):
    parts = input_str.strip().split()
    if len(parts) < 3:
        return "-1\n"

    maxx, maxy, w = map(int, parts)
    limit = max(maxx, maxy)

    def rev(n):
        return int(str(n)[::-1])

    # Precompute rev values
    rev_list = [0] * (limit + 1)
    for i in range(1, limit + 1):
        rev_list[i] = rev(i)

    # Group numbers by type key (rev(i), i)
    # Two numbers a and b form a lucky pair when a*rev(b) == rev(a)*b
    # This is equivalent to grouping by the pair (rev(i), i)
    types = defaultdict(list)
    for i in range(1, limit + 1):
        ri = rev_list[i]
        if ri > 0:
            types[(ri, i)].append(i)

    # Sort each group for binary search
    for lst in types.values():
        lst.sort()

    def count_lucky(x, y):
        """Count lucky tickets in range [1,x] × [1,y]"""
        total = 0
        for key, nums in types.items():
            x_count = bisect_right(nums, x)
            if x_count == 0:
                continue

            if key[0] == key[1]:
                # Self-inverse case (palindromes): rev(a) == a
                y_count = bisect_right(nums, y)
                total += x_count * y_count
            else:
                # Need complementary type with swapped keys
                inv_key = (key[1], key[0])
                if inv_key in types:
                    nums_b = types[inv_key]
                    y_count = bisect_right(nums_b, y)
                    total += x_count * y_count
        return total

    best = None
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            cnt = count_lucky(x, y)
            if cnt >= w:
                prod = x * y
                if best is None or prod < best[0]:
                    best = (prod, x, y)

    if best:
        return f"{best[1]} {best[2]}\n"
    return "-1\n"

def solution(input_data):
    input_data = input_data.strip()

    # Parse n and m
    n, m = map(int, input_data.split('\n')[0].split())

    # Parse attempts
    attempts = []
    counts = []
    for i in range(1, m + 1):
        line = input_data.split('\n')[i]
        s, c = line.strip().split()
        attempts.append(s)
        counts.append(int(c))

    # Convert to bit lists for easier manipulation
    bit_attempts = [list(map(int, list(s))) for s in attempts]

    # For small n, use direct brute force with recursion
    if n <= 18:
        def search(idx, current):
            if idx == n:
                for r in range(m):
                    # Count how many bits match attempt r
                    matches = sum(a == c for a, c in zip(bit_attempts[r], current))
                    if matches != counts[r]:
                        return 0
                return 1

            # Try both bit values
            total = 0
            for bit in [0, 1]:
                total += search(idx + 1, current + [bit])
            return total

        return str(search(0, []))

    # For larger n, use meet-in-the-middle approach
    # Split positions into left half (0 to half-1) and right half (half to n-1)
    half = n // 2

    left_patterns = {}

    # Generate all possible assignments for left half
    for left_code in range(1 << half):
        # Calculate match counts with each attempt
        match_counts = []
        for r in range(m):
            match = 0
            for i in range(half):
                bit = ((left_code >> i) & 1)
                if bit == bit_attempts[r][i]:
                    match += 1
            match_counts.append(match)

        # Use tuple as key for grouping
        key = tuple(match_counts)
        left_patterns[key] = left_patterns.get(key, 0) + 1

    result = 0

    # Now iterate through all right half assignments
    for right_code in range(1 << (n - half)):
        match_counts = []
        for r in range(m):
            match = 0
            for i in range(n - half):
                bit = ((right_code >> i) & 1)
                if bit == bit_attempts[r][half + i]:
                    match += 1
            match_counts.append(match)

        # Calculate how many more matches needed from left half
        needed = tuple(counts[r] - match_counts[r] for r in range(m))

        # If needed matches can be satisfied by some left code
        if needed in left_patterns:
            result += left_patterns[needed]

    return str(result)


